/* Daily staff presence and supervisor review. Requires migration 044. */
let SUPERVISION_ROWS=[],SUPERVISION_DATE='',SUPERVISION_FILTER={dept:'',state:'',q:''},SUPERVISION_READY=false;
function supervisionToday(){return typeof bangkokTodayISO==='function'?bangkokTodayISO():new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok'}).format(new Date());}
function supervisionCanManage(){return !!ACCESS_PROFILE&&['lead','exec','admin'].includes(AUTH_DB_ROLE);}
function supervisionDateTime(v){if(!v)return 'ยังไม่เคยเข้าใช้';return new Intl.DateTimeFormat('th-TH',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(v));}
function supervisionStatusLabel(v){return v==='approved'?'อนุมัติแล้ว':v==='needs_followup'?'ต้องติดตาม':'รอตรวจ';}
async function loadDailySupervision(date=SUPERVISION_DATE||supervisionToday(),quiet=false){
  if(!SB||!ACCESS_PROFILE)return;
  SUPERVISION_DATE=date;
  const r=await SB.rpc('daily_supervision_rows',{p_work_date:date});
  if(r.error){SUPERVISION_READY=false;if(!quiet&&VIEW==='supervision')main.innerHTML=`${crumb('หน้าแรก','ตรวจงานประจำวัน')}<div class="ai-note"><b>ยังเปิดหน้าตรวจงานไม่ได้</b><br>กรุณารัน Migration 044 · ${esc(r.error.message||'')}</div>`;return;}
  SUPERVISION_ROWS=r.data||[];SUPERVISION_READY=true;
  if(VIEW==='supervision')RENDER.supervision();
  if(VIEW==='dash')RENDER.dash();
  supervisionNotifyMissing();
}
function supervisionEntryCount(r){return Number(r.entry_count||0);}
function supervisionVisibleRows(){const q=SUPERVISION_FILTER.q.trim().toLowerCase();return SUPERVISION_ROWS.filter(r=>(!SUPERVISION_FILTER.dept||r.department_code===SUPERVISION_FILTER.dept)&&(!SUPERVISION_FILTER.state||(SUPERVISION_FILTER.state==='missing'?supervisionEntryCount(r)===0:SUPERVISION_FILTER.state==='entered'?supervisionEntryCount(r)>0:SUPERVISION_FILTER.state==='online'?r.is_online:SUPERVISION_FILTER.state==='pending'?!r.review_status:r.review_status===SUPERVISION_FILTER.state))&&(!q||`${r.display_name} ${r.email} ${r.position_title}`.toLowerCase().includes(q)));}
function supervisionSummary(){const rows=SUPERVISION_ROWS;return {total:rows.length,online:rows.filter(r=>r.is_online).length,entered:rows.filter(r=>supervisionEntryCount(r)>0).length,entries:rows.reduce((n,r)=>n+supervisionEntryCount(r),0),missing:rows.filter(r=>supervisionEntryCount(r)===0).length,pending:rows.filter(r=>!r.review_status).length,approved:rows.filter(r=>r.review_status==='approved').length};}
function supervisionAlertHtml(){if(!supervisionCanManage()||!SUPERVISION_READY)return '';const s=supervisionSummary();return `<div class="supervision-alert ${s.missing?'':'ok'}"><div><b>${s.missing?`${nf(s.missing)} คนยังไม่ลงข้อมูลวันนี้`:'พนักงานในขอบเขตลงข้อมูลวันนี้แล้ว'}</b><small>กรอกผ่าน Company Hub แล้ว ${nf(s.entered)} คน · ${nf(s.entries)} รายการจริง (กิจกรรม ปัญหา และงานบอร์ด) · ออนไลน์ขณะนี้ ${nf(s.online)} คน · รอหัวหน้าตรวจ ${nf(s.pending)} คน</small></div><button class="tbtn ${s.missing?'primary':''}" onclick="go('supervision')">เปิดรายการตรวจงาน</button></div>`;}
function supervisionInjectAlert(){const target=main.querySelector('.page-h');if(target&&!main.querySelector('.supervision-alert'))target.insertAdjacentHTML('afterend',supervisionAlertHtml());}
function supervisionRender(){
  if(!supervisionCanManage()){main.innerHTML=`${crumb('หน้าแรก','ตรวจงานประจำวัน')}<div class="ai-note">เมนูนี้สำหรับหัวหน้า ผู้บริหาร และผู้ดูแลระบบ</div>`;return;}
  if(!SUPERVISION_READY){main.innerHTML=`${crumb('หน้าแรก','ตรวจงานประจำวัน')}<div class="card pad">กำลังโหลดข้อมูลจริงตามสิทธิ์…</div>`;loadDailySupervision(SUPERVISION_DATE||supervisionToday());return;}
  const rows=supervisionVisibleRows(),s=supervisionSummary(),depts=[...new Set(SUPERVISION_ROWS.map(r=>r.department_code).filter(Boolean))].sort();
  main.innerHTML=`${crumb('หน้าแรก','ตรวจงานประจำวัน')}<div class="page-h"><div><h1>ตรวจงานประจำวัน</h1><p>ดูการลงงาน สถานะใช้งาน และอนุมัติสรุปงานของพนักงานก่อนจบวัน</p>${sourceBadge('live','ข้อมูล Production','จำกัดตามแผนกที่คุณจัดการ')}</div><button class="tbtn" onclick="enableSupervisionNotifications()">${typeof Notification!=='undefined'&&Notification.permission==='granted'?'✓ แจ้งเตือนเบราว์เซอร์เปิดแล้ว':'เปิดแจ้งเตือนเบราว์เซอร์'}</button></div>
  ${supervisionAlertHtml()}<div class="stats supervision-stats" style="margin-bottom:14px"><div class="stat"><div class="lbl">พนักงานในขอบเขต</div><div class="val">${nf(s.total)}</div></div><div class="stat"><div class="lbl">ผู้กรอกผ่านระบบ</div><div class="val" style="color:var(--green)">${nf(s.entered)}</div><div class="sub">รวม ${nf(s.entries)} รายการจริง</div></div><div class="stat"><div class="lbl">ออนไลน์</div><div class="val" style="color:var(--green)">${nf(s.online)}</div><div class="sub">เห็นภายใน 3 นาที</div></div><div class="stat"><div class="lbl">ยังไม่ลงข้อมูล</div><div class="val" style="color:var(--amber)">${nf(s.missing)}</div></div><div class="stat"><div class="lbl">อนุมัติแล้ว</div><div class="val">${nf(s.approved)}</div><div class="sub">รอตรวจ ${nf(s.pending)}</div></div></div>
  <div class="card"><div class="pad supervision-toolbar"><div class="field"><label>วันที่ทำงาน</label><input class="fin" type="date" value="${SUPERVISION_DATE}" onchange="loadDailySupervision(this.value)"></div><div class="field"><label>แผนก</label><select class="fin" onchange="SUPERVISION_FILTER.dept=this.value;RENDER.supervision()"><option value="">ทุกแผนก</option>${depts.map(d=>`<option value="${esc(d)}" ${SUPERVISION_FILTER.dept===d?'selected':''}>${esc(deptName(d))}</option>`).join('')}</select></div><div class="field"><label>สถานะ</label><select class="fin" onchange="SUPERVISION_FILTER.state=this.value;RENDER.supervision()"><option value="">ทั้งหมด</option><option value="entered" ${SUPERVISION_FILTER.state==='entered'?'selected':''}>ลงข้อมูลแล้ว</option><option value="missing" ${SUPERVISION_FILTER.state==='missing'?'selected':''}>ยังไม่ลงข้อมูล</option><option value="online" ${SUPERVISION_FILTER.state==='online'?'selected':''}>ออนไลน์</option><option value="pending" ${SUPERVISION_FILTER.state==='pending'?'selected':''}>รอตรวจ</option><option value="approved" ${SUPERVISION_FILTER.state==='approved'?'selected':''}>อนุมัติแล้ว</option><option value="needs_followup" ${SUPERVISION_FILTER.state==='needs_followup'?'selected':''}>ต้องติดตาม</option></select></div><div class="field" style="flex:1"><label>ค้นหาพนักงาน</label><input class="fin" value="${esc(SUPERVISION_FILTER.q)}" placeholder="ชื่อ อีเมล หรือตำแหน่ง" oninput="SUPERVISION_FILTER.q=this.value;clearTimeout(window._svq);window._svq=setTimeout(RENDER.supervision,200)"></div></div>
  <div style="overflow:auto"><table class="datatable supervision-table"><thead><tr><th>พนักงาน</th><th>สถานะใช้งาน</th><th>รายการที่กรอกจริงวันนี้</th><th>งานที่รับผิดชอบและอัปเดตวันนี้</th><th>ผลตรวจหัวหน้า</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr class="${supervisionEntryCount(r)===0?'missing-entry':''}"><td><div class="supervision-name"><span class="supervision-avatar">${esc((r.display_name||r.email||'?').slice(0,1).toUpperCase())}</span><div><b>${esc(r.display_name||r.email)}</b><br><span class="muted">${esc(r.position_title||'พนักงาน')} · ${esc(deptName(r.department_code))}</span></div></div></td><td><span class="presence ${r.is_online?'online':'offline'}">${r.is_online?'ออนไลน์':'ออฟไลน์'}</span><br><span class="muted">${supervisionDateTime(r.last_seen_at)}${r.last_page?` · ${esc(NAV[r.last_page]?.t||r.last_page)}`:''}</span></td><td><button class="supervision-entry-link" ${supervisionEntryCount(r)?`onclick="openDailyEntries('${r.profile_id}')"`:'disabled'}><b>รวม ${nf(supervisionEntryCount(r))}</b><span>กิจกรรม ${nf(r.activity_count)} · ปัญหา ${nf(r.issue_count)} · งานบอร์ด ${nf(r.created_task_count)}</span><small>${supervisionEntryCount(r)?'กดดูรายการจริง':'ยังไม่มีรายการที่กรอกผ่านระบบ'}</small></button></td><td><div class="supervision-counts"><span>เสร็จ ${nf(r.completed_task_count)}</span><span>ค้าง ${nf(r.open_task_count)}</span></div></td><td><span class="review-pill ${r.review_status||''}">${supervisionStatusLabel(r.review_status)}</span>${r.reviewer_name?`<br><span class="muted">โดย ${esc(r.reviewer_name)} · ${supervisionDateTime(r.reviewed_at)}</span>`:''}</td><td><button class="tbtn sm primary" onclick="openDailyReview('${r.profile_id}')">ตรวจงาน</button> <button class="tbtn sm" onclick="openEmployeeAudit('${r.profile_id}')">ประวัติ</button></td></tr>`).join('')||'<tr><td colspan="6">ไม่พบรายการตามตัวกรอง</td></tr>'}</tbody></table></div><div class="pad supervision-footnote">“ยังไม่ลงข้อมูล” หมายถึงไม่มีรายการที่สร้างผ่าน Company Hub ในวันที่เลือก ทั้งกิจกรรม ปัญหา และงานบอร์ด โดยไม่นับรายการที่ระบุว่า “ทดสอบ” · สถานะนี้ไม่ใช่ข้อมูลขาดงาน</div></div>`;
}
function openDailyReview(profileId){const r=SUPERVISION_ROWS.find(x=>x.profile_id===profileId);if(!r)return;const has=supervisionEntryCount(r)>0;showModal(`<div class="modal-h"><div><h3>ตรวจงาน · ${esc(r.display_name||r.email)}</h3><div class="muted">${esc(deptName(r.department_code))} · ${SUPERVISION_DATE}</div></div><button class="x" onclick="closeModal()">×</button></div><div class="pad"><div class="ai-note"><b>รายการที่กรอกผ่านระบบ ${nf(supervisionEntryCount(r))} รายการ</b><br>กิจกรรม ${nf(r.activity_count)} · ปัญหา ${nf(r.issue_count)} · งานบอร์ด ${nf(r.created_task_count)} · รายการเสร็จ ${nf(r.completed_entry_count)}<br><button class="tbtn sm" style="margin-top:8px" ${has?`onclick="openDailyEntries('${r.profile_id}')"`:'disabled'}>เปิดรายการจริง →</button></div><div class="review-checks"><label><input id="srEntry" type="checkbox" ${has?'checked':''}> มีรายการประจำวันที่เปิดตรวจสอบได้</label><label><input id="srOutstanding" type="checkbox"> ตรวจงานค้าง งานต่อเนื่อง และงานที่ติดปัญหาแล้ว</label><label><input id="srEvidence" type="checkbox"> งานที่ระบุว่าเสร็จมีผลลัพธ์หรือหลักฐานเพียงพอ</label><label><input id="srConfirm" type="checkbox"> ยืนยันสรุปงานกับพนักงานแล้ว</label></div><div class="field"><label>หมายเหตุหัวหน้า</label><textarea class="fin" id="srNote" rows="3" maxlength="2000" placeholder="สิ่งที่ต้องติดตาม หรือเหตุผลที่อนุมัติ">${esc(r.review_note||'')}</textarea></div><div style="display:flex;gap:8px;justify-content:flex-end"><button class="tbtn" onclick="saveDailyReview('${r.profile_id}','${esc(r.department_code)}','needs_followup')">ต้องติดตาม</button><button class="tbtn primary" onclick="saveDailyReview('${r.profile_id}','${esc(r.department_code)}','approved')">อนุมัติงานวันนี้</button></div></div>`);}
function supervisionEntryLabel(type){return type==='activity'?'กิจกรรม':type==='issue'?'ปัญหา':'งานบอร์ด';}
function openSupervisionEntry(encodedType,encodedId){const type=decodeURIComponent(encodedType),id=decodeURIComponent(encodedId);if(type==='activity'){const row=ACTIVITY_ROWS.find(r=>String(r.id)===String(id));if(row)return openBoardActivity(id);closeModal();ACTIVITY_FILTER.query=id;ACTIVITY_PAGE=1;return go('activity');}if(type==='issue'){if(PROBLEMS.some(p=>String(p.id)===String(id)))return openProblem(id);closeModal();return go('problems');}if(TASKS.some(t=>String(t.id)===String(id)))return openTask(id);closeModal();go('board');}
async function openDailyEntries(profileId){const person=SUPERVISION_ROWS.find(x=>x.profile_id===profileId);if(!person)return;showModal(`<div class="modal-h"><div><h3>รายการที่กรอกจริง · ${esc(person.display_name||person.email)}</h3><div class="muted">${SUPERVISION_DATE} · กิจกรรม ปัญหา และงานบอร์ด</div></div><button class="x" onclick="closeModal()">×</button></div><div class="pad">กำลังโหลดรายการจริง…</div>`);const result=await SB.rpc('daily_supervision_entries',{p_work_date:SUPERVISION_DATE,p_employee:profileId});if(result.error){modal.innerHTML=`<div class="modal-h"><h3>เปิดรายการไม่สำเร็จ</h3><button class="x" onclick="closeModal()">×</button></div><div class="pad ai-note">${esc(result.error.message||'')}</div>`;return;}const entries=result.data||[];modal.innerHTML=`<div class="modal-h"><div><h3>รายการที่กรอกจริง · ${esc(person.display_name||person.email)}</h3><div class="muted">${SUPERVISION_DATE} · ${nf(entries.length)} รายการ</div></div><button class="x" onclick="closeModal()">×</button></div><div class="pad supervision-entry-list">${entries.map(e=>`<button class="supervision-entry-card" onclick="openSupervisionEntry('${esc(encodeURIComponent(e.entry_type))}','${esc(encodeURIComponent(e.route_id||e.entry_id))}')"><span class="supervision-entry-type is-${esc(e.entry_type)}">${supervisionEntryLabel(e.entry_type)}</span><span class="supervision-entry-main"><b>${esc(e.title||'-')}</b>${e.detail?`<small>${esc(e.detail)}</small>`:''}<small>${esc(deptName(e.department_code))} · ${supervisionDateTime(e.occurred_at)} · ${esc(e.status||'-')}</small></span><span class="supervision-entry-arrow">เปิด →</span></button>`).join('')||'<div class="muted">ไม่พบรายการจริงในวันที่เลือก</div>'}</div>`;}
async function saveDailyReview(profileId,dept,status){const args={p_work_date:SUPERVISION_DATE,p_employee:profileId,p_department:dept,p_status:status,p_has_daily_entry:document.getElementById('srEntry').checked,p_outstanding_reviewed:document.getElementById('srOutstanding').checked,p_completed_evidence_checked:document.getElementById('srEvidence').checked,p_employee_summary_confirmed:document.getElementById('srConfirm').checked,p_note:val('srNote')};const r=await SB.rpc('save_daily_work_review',args);if(r.error){toast('บันทึกผลตรวจไม่สำเร็จ · '+r.error.message,'info');return;}closeModal();toast(status==='approved'?'อนุมัติงานวันนี้แล้ว':'บันทึกเป็นรายการต้องติดตามแล้ว');await loadDailySupervision(SUPERVISION_DATE);}
async function openEmployeeAudit(profileId){const person=SUPERVISION_ROWS.find(x=>x.profile_id===profileId);showModal(`<div class="modal-h"><h3>ประวัติเปิดดู / แก้ไข · ${esc(person?.display_name||person?.email||'')}</h3><button class="x" onclick="closeModal()">×</button></div><div class="pad">กำลังโหลด…</div>`);const from=SUPERVISION_DATE+'T00:00:00+07:00',to=SUPERVISION_DATE+'T23:59:59+07:00';const q=await SB.from('work_audit_events').select('*').eq('actor_profile_id',profileId).gte('event_at',from).lte('event_at',to).order('event_at',{ascending:false}).limit(300);if(q.error){toast(q.error.message,'info');return;}const label={view:'เปิดดู',create:'สร้าง',edit:'แก้ไข',delete:'ลบ',review:'ตรวจรับ'};modal.innerHTML=`<div class="modal-h"><div><h3>ประวัติเปิดดู / แก้ไข</h3><div class="muted">${esc(person?.display_name||person?.email||'')} · ${SUPERVISION_DATE}</div></div><button class="x" onclick="closeModal()">×</button></div><div class="pad audit-list">${(q.data||[]).map(e=>`<div class="audit-row"><b>${label[e.event_type]||esc(e.event_type)}</b><span>${esc(e.entity_type)} ${esc(e.entity_id||'')} ${e.department_code?'· '+esc(deptName(e.department_code)):''}</span><span class="muted">${supervisionDateTime(e.event_at)}</span></div>`).join('')||'<div class="muted">ยังไม่มีประวัติในวันที่เลือก</div>'}</div>`;}
async function enableSupervisionNotifications(){if(typeof Notification==='undefined'){toast('เบราว์เซอร์นี้ไม่รองรับการแจ้งเตือน','info');return;}const p=await Notification.requestPermission();toast(p==='granted'?'เปิดแจ้งเตือนแล้ว':'ยังไม่ได้อนุญาตการแจ้งเตือน',p==='granted'?'':'info');if(p==='granted')supervisionNotifyMissing(true);}
function supervisionNotifyMissing(force=false){if(!SUPERVISION_READY||!supervisionCanManage()||typeof Notification==='undefined'||Notification.permission!=='granted')return;const s=supervisionSummary(),key=`ch-supervision-notified-${SUPERVISION_DATE}`;if(!s.missing||(!force&&localStorage.getItem(key)))return;new Notification('Company Hub · ตรวจงานประจำวัน',{body:`${s.missing} คนยังไม่ลงงานวันที่ ${SUPERVISION_DATE} · รอหัวหน้าตรวจ ${s.pending} คน`});localStorage.setItem(key,'1');}
async function supervisionTouch(){if(!SB||!ACCESS_PROFILE||document.visibilityState==='hidden')return;try{await SB.rpc('touch_employee_presence',{p_page:VIEW||''});}catch(e){}}
async function supervisionRecordView(type,id,dept){if(!SB||!ACCESS_PROFILE)return;try{await SB.rpc('record_work_view',{p_entity_type:type,p_entity_id:String(id||''),p_department:dept||null,p_page:VIEW||''});}catch(e){}}

NAV.supervision={ic:'i-check',t:'ตรวจงานประจำวัน'};
if(!NAVGROUPS[1].items.includes('supervision'))NAVGROUPS[1].items.unshift('supervision');
for(const role of ['lead','exec'])if(!ROLE_ALLOW[role].includes('supervision'))ROLE_ALLOW[role].splice(1,0,'supervision');
for(const role of ['lead','exec'])if(!SIMPLE_ALLOW[role].includes('supervision'))SIMPLE_ALLOW[role].splice(1,0,'supervision');
RENDER.supervision=supervisionRender;
const supervisionDash=RENDER.dash;RENDER.dash=function(){const out=supervisionDash.apply(this,arguments);supervisionInjectAlert();return out;};
const supervisionGo=go;go=function(v,arg){const out=supervisionGo(v,arg);supervisionTouch();return out;};
const supervisionOpenTask=openTask;openTask=function(id){const t=TASKS.find(x=>x.id===id);supervisionRecordView('task',t?.dbId||id,t?.dept);return supervisionOpenTask(id);};
const supervisionOpenGraphic=openGraphicJob;openGraphicJob=async function(id){const j=GRAPHIC_JOBS.find(x=>x.id===id);supervisionRecordView('graphic_job',id,j?.department_code||'GRAPHIC');return supervisionOpenGraphic(id);};
const supervisionOpenIssue=openProblem;openProblem=function(id){const p=PROBLEMS.find(x=>x.id===id);supervisionRecordView('issue',id,p?.dept);return supervisionOpenIssue(id);};
const supervisionLogin=onLoggedIn;onLoggedIn=async function(session){const ok=await supervisionLogin(session);if(ok){await supervisionTouch();await loadDailySupervision(supervisionToday(),true);clearInterval(window._supervisionHeartbeat);window._supervisionHeartbeat=setInterval(supervisionTouch,60000);}return ok;};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')supervisionTouch();});
